#include <iostream>

#include <iomanip>

using namespace std;

long long sum(long long n,long long d){long long k=n/d;return d*k*(k+1)/2;}

int main(){long long m,n;cin>>m>>n;

long long total=sum(n,5)-sum(m-1,5);

long long count=n/6-(m-1)/6;

double avg=count?(sum(n,6)-sum(m-1,6))/(double)count:0.0;

cout<<total<<' '<<fixed<<setprecision(0)<<avg<<'\n';}
